package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonGenerator;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectCodec;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.*;

/**
 * Unit tests for UTF8JsonGenerator#writeNumber(BigDecimal)
 */
public class UTF8JsonGenerator_writeNumber_TriageGen0Test {

    private ByteArrayOutputStream outputStream;
    private IOContext ioContext;
    private ObjectCodec codec;
    private UTF8JsonGenerator generator;

    @Before
    public void setUp() {
        outputStream = new ByteArrayOutputStream();
        ioContext = IOContext.bootstrap();
        codec = mock(ObjectCodec.class);
        // Creating a spy to control internal configuration flags if necessary, 
        // though in a real Jackson environment, these are set via JsonGenerator.Feature
        generator = spy(new UTF8JsonGenerator(ioContext, 0, codec, outputStream));
    }

    @Test
    public void testWriteNumber_NullValue() throws IOException {
        generator.writeNumber((BigDecimal) null);

        // Based on code: if (value == null) { _writeNull(); }
        // We verify that _writeNull was called. 
        // In a real implementation, this writes "null" to the stream.
        verify(generator).writeNull();
    }

    @Test
    public void testWriteNumber_WithNumbersAsStringsTrue() throws IOException {
        // We need to simulate _cfgNumbersAsStrings being true.
        // Since we cannot easily change private fields via standard API without reflection,
        // we mock the behavior or use a subclass/spy approach if the field was protected.
        // However, since we are testing the logic provided:

        // Mocking the internal _cfgNumbersAsStrings behavior via spy is tricky because it's a field.
        // In a real Jackson test suite, we would use JsonGenerator.Feature.WRITE_NUMBERS_AS_STRINGS.

        // For the purpose of this unit test targeting the provided snippet:
        // We assume a setup where _cfgNumbersAsStrings is true.

        // Since we are using a spy, we simulate the branch by overriding the behavior 
        // or assuming the environment allows setting features.

        // Let's use reflection to set the private field to ensure branch coverage.
        try {
            java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
            field.setAccessible(true);
            field.set(generator, true);
        } catch (Exception e) {
            // If field is not accessible, this test might fail, but it's the only way to hit the branch
        }

        BigDecimal value = new BigDecimal("123.45");

        // The code calls _writeQuotedRaw(_asString(value))
        // We need to mock _asString to return the expected string
        doReturn("123.45").when(generator)._asString(value);

        generator.writeNumber(value);

        verify(generator)._verifyValueWrite(JsonGenerator.Feature.WRITE_NUMBER.toString()); // Simplified check
        verify(generator)._writeQuotedRaw("123.45");
    }

    @Test
    public void testWriteNumber_WithNumbersAsStringsFalse() throws IOException {
        // Set _cfgNumbersAsStrings to false
        try {
            java.lang.reflect.Field field = UTF8JsonGenerator.class.getDeclaredField("_cfgNumbersAsStrings");
            field.setAccessible(true);
            field.set(generator, false);
        } catch (Exception e) {
            // Handle exception
        }

        BigDecimal value = new BigDecimal("123.45");

        generator.writeNumber(value);

        // Verify _verifyValueWrite was called
        verify(generator)._verifyValueWrite(anyString());
        // Verify that _writeQuotedRaw was NOT called because of the else branch
        verify(generator, never())._writeQuotedRaw(anyString());
    }

    @Test
    public void testWriteNumber_VerifyValueWriteException() throws IOException {
        // Test the branch where _verifyValueWrite throws an exception
        doThrow(new IOException("Verify failed")).when(generator)._verifyValueWrite(anyString());

        try {
            generator.writeNumber(new BigDecimal("10"));
        } catch (IOException e) {
            assertEquals("Verify failed", e.getMessage());
        }
    }
}
